## Key Concepts
- Trie with per-node pass-through counts; O(length) ops; dynamic memory.
- Duplicate handling via cnt; pruning unused nodes to bound memory.

## Code Example
```javascript
class TrieNode {
  constructor(){ this.next = new Map(); this.cnt = 0; }
}
class Trie {
  constructor(){ this.root = new TrieNode(); }
  insert(word){ let node=this.root; for(let ch of word){ if(!node.next.has(ch)) node.next.set(ch,new TrieNode()); node = node.next.get(ch); node.cnt++; } }
  erase(word){ let stack=[]; let node=this.root; for(let ch of word){ if(!node.next.has(ch)) return; node = node.next.get(ch); stack.push([node,ch]); } // decrement
    for(let [nd] of stack){ nd.cnt--; }
  }
  countWithPrefix(prefix){ let node=this.root; for(let ch of prefix){ if(!node.next.has(ch)) return 0; node = node.next.get(ch); } return node.cnt; }
}
```

## Why This Is Asked

Tests ability to combine a circular buffer with a monotonic deque to support rolling-window stats efficiently; checks edge-cases with duplicates and partial windows.

## Key Concepts

- Circular buffers
- Monotonic deque for max
- Running sum
- Amortized analysis

## Code Example

```javascript
class RollingWindow {
  constructor(n) {
    this.n = n;
    this.buf = new Array(n);
    this.head = 0; // points to oldest element
    this.size = 0;
    this.sum = 0;
    this.maxDQ = []; // decreasing values
  }
  push(v) {
    // evict oldest if full
    if (this.size === this.n) {
      const old = this.buf[this.head];
      this.sum -= old;
      if (this.maxDQ[0] === old) this.maxDQ.shift();
      this.head = (this.head + 1) % this.n;
      this.size--;
    }
    const idx = (this.head + this.size) % this.n;
    this.buf[idx] = v;
    this.size++;
    this.sum += v;
    while (this.maxDQ.length && this.maxDQ[this.maxDQ.length - 1] < v) this.maxDQ.pop();
    this.maxDQ.push(v);
  }
  sumWindow() {
    return this.sum;
  }
  maxWindow() {
    return this.maxDQ.length ? this.maxDQ[0] : undefined;
  }
}
```

